@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource-variable/jetbrains-mono";

/* Light (faithful): warm paper page #f7f7f4, panels #f2f1ed, ink #26251e for text and the
   dark pill (hover #3b3a33), ink-60% secondary text, ink-5…10% hairlines, a pale pill #e6e5e0
   that darkens to #e1e0db, link cards that darken to #ebeae5, and orange #f54e00 for links. */
:root {
  --background: #f7f7f4;
  --foreground: #26251e;
  --card: #f2f1ed;
  --card-foreground: #26251e;
  --popover: #fcfcfb;
  --popover-foreground: #26251e;
  --primary: #26251e;
  --primary-foreground: #f7f7f4;
  --secondary: #e6e5e0;
  --secondary-foreground: #26251e;
  --muted: #ebeae5;
  --muted-foreground: #7a7975;
  --accent: #e1e0db;
  --accent-foreground: #26251e;
  --destructive: #cf2d56;
  --destructive-foreground: #f7f7f4;
  --border: rgb(38 37 30 / 8%);
  --input: rgb(38 37 30 / 20%);
  --ring: rgb(38 37 30 / 40%);
  --highlight: #f54e00;
  --highlight-foreground: #f7f7f4;
  --glow: #d9d5cf;
  --chart-1: #f54e00;
  --chart-2: #1f8a65;
  --chart-3: #9fbbe0;
  --chart-4: #c0a8dd;
  --chart-5: #dfa88f;
  --sidebar: #f2f1ed;
  --sidebar-foreground: #26251e;
  --sidebar-primary: #26251e;
  --sidebar-primary-foreground: #f7f7f4;
  --sidebar-accent: #e6e5e0;
  --sidebar-accent-foreground: #26251e;
  --sidebar-border: rgb(38 37 30 / 8%);
  --sidebar-ring: rgb(38 37 30 / 40%);

  --typeface-body: "Hanken Grotesk Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-mono: "JetBrains Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  /* cards, tiles and media frames: 4px; buttons are full pills */
  --radius: 0.25rem;
  /* the 1300px content frame */
  --page-width: 81.25rem;
  /* 19px on phones, up to 40px on tablets */
  --page-gutter: clamp(1.1875rem, 0.6rem + 2.4vw, 2.5rem);
  --section-y: clamp(3.8125rem, 3.25rem + 1vw, 4.1875rem);
}

/* Dark (sibling): warm near-black page #14120b, panels #1b1913, off-white ink #edecec, the
   pill inverts to ink-on-paper, hairlines in white 8%, the same orange. */
.dark {
  --background: #14120b;
  --foreground: #edecec;
  --card: #1b1913;
  --card-foreground: #edecec;
  --popover: #22201a;
  --popover-foreground: #edecec;
  --primary: #edecec;
  --primary-foreground: #14120b;
  --secondary: #2a2821;
  --secondary-foreground: #edecec;
  --muted: #24221b;
  --muted-foreground: #8f8d86;
  --accent: #302e27;
  --accent-foreground: #edecec;
  --destructive: #e5577a;
  --destructive-foreground: #14120b;
  --border: rgb(237 236 236 / 9%);
  --input: rgb(237 236 236 / 18%);
  --ring: rgb(237 236 236 / 40%);
  --highlight: #ff6a1f;
  --highlight-foreground: #14120b;
  --glow: #3a3628;
  --chart-1: #ff6a1f;
  --chart-2: #3fb488;
  --chart-3: #9fbbe0;
  --chart-4: #c0a8dd;
  --chart-5: #dfa88f;
  --sidebar: #1b1913;
  --sidebar-foreground: #edecec;
  --sidebar-primary: #edecec;
  --sidebar-primary-foreground: #14120b;
  --sidebar-accent: #2a2821;
  --sidebar-accent-foreground: #edecec;
  --sidebar-border: rgb(237 236 236 / 9%);
  --sidebar-ring: rgb(237 236 236 / 40%);
}
